import 'package:drift/drift.dart';

part 'practice_db.g.dart';

// The local practice database (ADR 0015): schema version 1. Only these declarations are generated code's input (`practice_db.g.dart`,
// drift_dev + build_runner, checked in and regenerated by CI); the store (practice_store.dart) uses plain SQL against these tables, so
// its behaviour does not depend on the names the generator picks.

/// One finished scale run. Written once when the run ends; append-only. The totals are a cache of [GradedNotes].
class Sessions extends Table {
  @override
  String get tableName => 'sessions';

  TextColumn get id => text().named('id')(); // UUIDv7
  IntColumn get startedAt => integer().named('started_at')(); // UTC milliseconds since the epoch
  IntColumn get endedAt => integer().named('ended_at')();
  TextColumn get mode => text().named('mode')(); // 'scale'
  TextColumn get instrument => text().named('instrument').withDefault(const Constant('violin'))();
  RealColumn get a4Hz => real().named('a4_hz')();
  TextColumn get tuning => text().named('tuning')(); // 'equal'
  TextColumn get scaleId => text().named('scale_id')();
  RealColumn get scorePercent => real().named('score_percent')();
  IntColumn get green => integer().named('green')();
  IntColumn get yellow => integer().named('yellow')();
  IntColumn get red => integer().named('red')();
  IntColumn get missed => integer().named('missed')();
  IntColumn get noteCount => integer().named('note_count')();

  @override
  Set<Column> get primaryKey => {id};
}

/// Every graded note of a run: the source of truth for the caches (ADR 0015 decision 4).
@DataClassName('GradedNoteRow')
class GradedNotes extends Table {
  @override
  String get tableName => 'graded_notes';

  TextColumn get sessionId => text().named('session_id').references(Sessions, #id, onDelete: KeyAction.cascade)();
  IntColumn get idx => integer().named('idx')(); // position in the scale
  IntColumn get midiNote => integer().named('midi_note')();
  TextColumn get string => text().named('string')(); // 'G', 'D', 'A' or 'E'
  IntColumn get finger => integer().named('finger')(); // 0 open, 1 to 4
  TextColumn get placement => text().named('placement').nullable()(); // 'low', 'high' or null
  TextColumn get grade => text().named('grade')(); // 'green', 'yellow', 'red' or 'missed'
  RealColumn get cents => real().named('cents').nullable()(); // null if missed
  RealColumn get tStart => real().named('t_start').nullable()(); // seconds from the start of the run; null if missed
  RealColumn get tEnd => real().named('t_end').nullable()();

  @override
  Set<Column> get primaryKey => {sessionId, idx};
}

/// Per (session, note, string, finger, placement) statistics: a cache, recomputed from [GradedNotes]. `placement` is '' for "none"
/// here (not null), because it is part of the primary key and SQLite treats nulls in a key as all different.
@DataClassName('NoteStatRow')
class NoteStats extends Table {
  @override
  String get tableName => 'note_stats';

  TextColumn get sessionId => text().named('session_id').references(Sessions, #id, onDelete: KeyAction.cascade)();
  IntColumn get midiNote => integer().named('midi_note')();
  TextColumn get string => text().named('string')();
  IntColumn get finger => integer().named('finger')();
  TextColumn get placement => text().named('placement')();
  IntColumn get count => integer().named('count')();
  IntColumn get green => integer().named('green')();
  IntColumn get yellow => integer().named('yellow')();
  IntColumn get red => integer().named('red')();
  IntColumn get missed => integer().named('missed')();
  RealColumn get meanCents => real().named('mean_cents').nullable()(); // null if every note was missed
  RealColumn get meanAbsCents => real().named('mean_abs_cents').nullable()();
  RealColumn get stdCents => real().named('std_cents').nullable()(); // population standard deviation of the played notes' cents
  RealColumn get totalMs => real().named('total_ms')();

  @override
  Set<Column> get primaryKey => {sessionId, midiNote, string, finger, placement};
}

/// Local preferences (key/value).
class Settings extends Table {
  @override
  String get tableName => 'settings';

  TextColumn get key => text().named('key')();
  TextColumn get value => text().named('value')();
  IntColumn get updatedAt => integer().named('updated_at')();

  @override
  Set<Column> get primaryKey => {key};
}

@DriftDatabase(tables: [Sessions, GradedNotes, NoteStats, Settings])
class PracticeDb extends _$PracticeDb {
  PracticeDb(super.e);

  @override
  int get schemaVersion => 1;

  @override
  MigrationStrategy get migration => MigrationStrategy(
        onCreate: (m) => m.createAll(),
        beforeOpen: (details) async {
          await customStatement('PRAGMA foreign_keys = ON');
        },
      );
}
